                        setDynamicSetupLoading(prev => ({ ...prev, [c.id]: false }));
                      }
                    }}
                    disabled={dynamicSetupLoading[c.id] || !dynamicSetupValue[c.id]}
                    style={{ padding: "6px 12px", background: "#3c6663", color: "#fff", border: "none", borderRadius: 6, fontSize: 12, fontWeight: 600, cursor: "pointer", opacity: dynamicSetupLoading[c.id] || !dynamicSetupValue[c.id] ? 0.5 : 1 }}
                  >
                    {dynamicSetupLoading[c.id] ? "Saving..." : "Save"}
                  </button>
                  <button onClick={() => setDynamicSetupState(prev => ({ ...prev, [c.id]: false }))} style={{ padding: "6px 12px", background: "none", border: "1px solid var(--border-subtle)", borderRadius: 6, color: "var(--text-sub)", fontSize: 12, fontWeight: 600, cursor: "pointer" }}>Cancel</button>
                </div>
              </div>
            )}
          </ServiceRow>
        );
      })}

      {/* ── Plugin Directory ── */}
      <div style={{ marginTop: 32, marginBottom: 16, paddingTop: 32, borderTop: "1px solid var(--border-subtle)" }}>
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-end" }}>
          <div>
            <div style={{ fontSize: 16, fontWeight: 700, color: "var(--text-main)" }}>OpenClaw Plugin Directory</div>
            <div style={{ fontSize: 13, color: "var(--text-sub)", marginTop: 4 }}>Enable raw native plugins for this agent.</div>
          </div>
          <input 
            type="text" 
            placeholder="Search plugins..." 
            value={pluginSearch}
            onChange={e => setPluginSearch(e.target.value)}
            style={{ padding: "8px 14px", borderRadius: 8, border: "1px solid var(--border-subtle)", background: "var(--surface-base)", color: "var(--text-main)", fontSize: 13, width: 220 }}
          />
        </div>
      </div>

      <div style={{ display: "grid", gridTemplateColumns: "1fr", gap: 12 }}>
        {connectors
          .filter(c => c.isPlugin)
          .filter(c => !pluginSearch || c.name.toLowerCase().includes(pluginSearch.toLowerCase()) || c.subtitle.toLowerCase().includes(pluginSearch.toLowerCase()))
          .map(c => (
            <ServiceRow
              key={c.id}
              icon={<span style={{ fontSize: 18 }}>{c.emoji || "🔌"}</span>}
              name={c.name}
              subtitle={c.subtitle}
              connected={dynamicStatuses[c.id] || false}
              enabled={dynamicEnabled[c.id]}
              onToggle={(enabled) => {
                setDynamicEnabled(prev => ({ ...prev, [c.id]: enabled }));
                toggleIntegration(c.id, enabled);
              }}
              onSetup={() => {
                alert(`To configure ${c.name}, follow the instructions in the OpenClaw documentation or run \`openclaw skills config ${c.name}\` in the terminal.`);
              }}
            />
          ))}
      </div>

      {/* Web Credentials */}
      {webCredentials.length > 0 && (
        <ServiceRow
          icon={<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="#2563eb" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><circle cx="12" cy="12" r="10"></circle><line x1="2" y1="12" x2="22" y2="12"></line><path d="M12 2a15.3 15.3 0 0 1 4 10 15.3 15.3 0 0 1-4 10 15.3 15.3 0 0 1-4-10 15.3 15.3 0 0 1 4-10z"></path></svg>}
          name="Web Credentials"
          subtitle="Allow this agent to seamlessly log into these websites."
          connected={true}
          enabled={webCredentials.some(c => agent.integrations.includes(`web_${c.domain}_${c.username}`))}
          statusBadge={null}
          onToggle={async (enabled) => {
             // If toggled globally, toggle all
             const toRemove = webCredentials.map(c => `web_${c.domain}_${c.username}`);
             if (enabled) {
                let newIntegrations = [...agent.integrations];
                toRemove.forEach(rm => {
                  if (!newIntegrations.includes(rm)) newIntegrations.push(rm);
                });
                const invoke = (window as any).__TAURI_INTERNALS__?.invoke || (async () => {});
                await invoke("update_agent_integrations", { agentId: agent.id, integrations: newIntegrations });
                useWorldStore.getState().setAgents(
                  useWorldStore.getState().agents.map(a => a.id === agent.id ? { ...a, integrations: newIntegrations } as AgentData : a)
                );
             } else {
                let newIntegrations = agent.integrations.filter(i => !toRemove.includes(i));
                const invoke = (window as any).__TAURI_INTERNALS__?.invoke || (async () => {});
                await invoke("update_agent_integrations", { agentId: agent.id, integrations: newIntegrations });
                useWorldStore.getState().setAgents(
                  useWorldStore.getState().agents.map(a => a.id === agent.id ? { ...a, integrations: newIntegrations } as AgentData : a)
                );
             }
          }}
        >
          <div style={{ display: "flex", flexDirection: "column", gap: 12 }}>
            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", paddingBottom: 8, borderBottom: "1px solid var(--border-subtle)" }}>
              <input 
                type="text" 
                placeholder="Search domain or username..." 
                value={webCredSearch}
                onChange={(e) => setWebCredSearch(e.target.value)}
                style={{ width: "200px", padding: "6px 10px", borderRadius: 6, border: "1px solid var(--border-subtle)", fontSize: 12, background: "var(--surface-base)", color: "var(--text-main)", outline: "none" }}
              />
              <div style={{ display: "flex", gap: 8 }}>
                <button 
                  onClick={async () => {
                     const toRemove = webCredentials.map(c => `web_${c.domain}_${c.username}`);
                     let newIntegrations = [...agent.integrations];
                     toRemove.forEach(rm => {
                       if (!newIntegrations.includes(rm)) newIntegrations.push(rm);
                     });
                     const invoke = (window as any).__TAURI_INTERNALS__?.invoke || (async () => {});
                     await invoke("update_agent_integrations", { agentId: agent.id, integrations: newIntegrations });
                     useWorldStore.getState().setAgents(
                       useWorldStore.getState().agents.map(a => a.id === agent.id ? { ...a, integrations: newIntegrations } as AgentData : a)
                     );
                  }}
                  style={{ padding: "4px 10px", fontSize: 11, fontWeight: 600, borderRadius: 4, border: "1px solid var(--border-subtle)", background: "var(--surface-raised)", cursor: "pointer", color: "var(--text-main)" }}
                >
                  Enable All
                </button>
                <button 
                  onClick={async () => {
                     const toRemove = webCredentials.map(c => `web_${c.domain}_${c.username}`);
                     let newIntegrations = agent.integrations.filter(i => !toRemove.includes(i));
                     const invoke = (window as any).__TAURI_INTERNALS__?.invoke || (async () => {});
                     await invoke("update_agent_integrations", { agentId: agent.id, integrations: newIntegrations });
                     useWorldStore.getState().setAgents(
                       useWorldStore.getState().agents.map(a => a.id === agent.id ? { ...a, integrations: newIntegrations } as AgentData : a)
                     );
                  }}
                  style={{ padding: "4px 10px", fontSize: 11, fontWeight: 600, borderRadius: 4, border: "1px solid var(--border-subtle)", background: "transparent", cursor: "pointer", color: "var(--text-main)" }}
                >
                  Disable All
                </button>
              </div>
            </div>
            {webCredentials
              .filter(cred => cred.domain.toLowerCase().includes(webCredSearch.toLowerCase()) || cred.username.toLowerCase().includes(webCredSearch.toLowerCase()))
              .map(cred => {
              const integrationKey = `web_${cred.domain}_${cred.username}`;
              const hasAccess = agent.integrations.includes(integrationKey);
              return (
                <div key={integrationKey} style={{ display: "flex", justifyContent: "space-between", alignItems: "center", borderBottom: "1px solid rgba(0,0,0,0.04)", paddingBottom: 8 }}>
                  <div>
                    <div style={{ fontSize: 13, fontWeight: 700, color: "var(--text-main)" }}>{cred.domain}</div>
                    <div style={{ fontSize: 11, color: "var(--text-sub)", marginTop: 2 }}>{cred.username}</div>
                  </div>
                  <Toggle enabled={hasAccess} onChange={() => toggleIntegration(integrationKey, !hasAccess)} />
                </div>
              );
            })}
          </div>
        </ServiceRow>
      )}

      {/* Capabilities & Skills */}
      <ServiceRow
        icon={<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="#6B6BAE" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z"></path></svg>}
        name="Capabilities & Skills"
        subtitle="Manage agent autonomy, capabilities, and OpenClaw skills."
        connected={true}
        enabled={agent.permissions.some(p => ["ext_network", "autonomous", "browser", "proxy", "vision", "canvas", "coding", "gog", "summarize"].includes(p.id) && p.enabled)}
        statusBadge={
          agent.permissions.some(p => ["ext_network", "autonomous", "browser", "proxy", "vision", "canvas", "coding", "gog", "summarize"].includes(p.id) && p.enabled)
            ? <span style={{ fontSize: 10, background: "#dcfce7", color: "#166534", padding: "1px 6px", borderRadius: 10, fontWeight: 600 }}>Active</span>
            : <span style={{ fontSize: 10, background: "var(--border-subtle)", color: "var(--text-sub)", padding: "1px 6px", borderRadius: 10, fontWeight: 600 }}>Disabled</span>
        }
        onToggle={async (enabled) => {
           const { invoke } = await import('@tauri-apps/api/core');
           const toggle = useWorldStore.getState().togglePermission;

           ["ext_network", "autonomous", "browser", "proxy", "vision", "canvas", "coding", "gog", "summarize"].forEach(pid => {
              const p = agent.permissions.find(x => x.id === pid);
              if (p && p.enabled !== enabled) toggle(agent.id, pid);
           });

           setTimeout(async () => {
             const currentAgent = useWorldStore.getState().agents.find(a => a.id === agent.id);
             if (!currentAgent) return;
             const capabilitiesObj: any = {};
             currentAgent.permissions.forEach(px => capabilitiesObj[px.id] = px.enabled);
             try { await invoke("update_agent_capabilities", { agentId: agent.id, capabilities: capabilitiesObj }); } catch (e) { console.error(e); }
           }, 100);
        }}
      >
        <div style={{ display: "flex", flexDirection: "column", gap: 16 }}>
          {agent.permissions.filter(p => ["ext_network", "autonomous", "browser", "proxy", "vision", "canvas", "coding", "gog", "summarize"].includes(p.id)).map((p, i, arr) => (
            <div key={p.id} style={{ display: "flex", justifyContent: "space-between", alignItems: "center", borderBottom: i < arr.length - 1 ? "1px solid rgba(0,0,0,0.04)" : "none", paddingBottom: i < arr.length - 1 ? 12 : 0 }}>
              <div>
                <div style={{ fontSize: 13, fontWeight: 700, color: "var(--text-main)" }}>{p.label}</div>
                <div style={{ fontSize: 11, color: "var(--text-sub)", marginTop: 4 }}>{p.description}</div>
              </div>
              <Toggle enabled={p.enabled} onChange={async () => {
                const { invoke } = await import('@tauri-apps/api/core');
                useWorldStore.getState().togglePermission(agent.id, p.id);
                setTimeout(async () => {
                  const currentAgent = useWorldStore.getState().agents.find(a => a.id === agent.id);
                  if (!currentAgent) return;
                  const capabilitiesObj: any = {};
                  currentAgent.permissions.forEach(px => capabilitiesObj[px.id] = px.enabled);
                  try { await invoke("update_agent_capabilities", { agentId: agent.id, capabilities: capabilitiesObj }); } catch (e) { console.error(e); }
                }, 100);
              }} />
            </div>
          ))}
        </div>
      </ServiceRow>

      {/* Payments & Financials */}
      <ServiceRow
        icon={<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="#2EB67D" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><rect x="2" y="5" width="20" height="14" rx="2"/><line x1="2" y1="10" x2="22" y2="10"/></svg>}
        name="Payments & Spending"
        subtitle="Manage agent spending limits, virtual cards, and payment execution."
        connected={true}
        enabled={agent.permissions.some(p => ["payments", "spend_auto"].includes(p.id) && p.enabled) || budget?.payments_enabled}
        statusBadge={
          (agent.permissions.some(p => ["payments", "spend_auto"].includes(p.id) && p.enabled) || budget?.payments_enabled)
            ? <span style={{ fontSize: 10, background: "#dcfce7", color: "#166534", padding: "1px 6px", borderRadius: 10, fontWeight: 600 }}>Active</span>
            : <span style={{ fontSize: 10, background: "var(--border-subtle)", color: "var(--text-sub)", padding: "1px 6px", borderRadius: 10, fontWeight: 600 }}>Disabled</span>
        }
        onToggle={async (enabled) => {
           const { invoke } = await import('@tauri-apps/api/core');
           const toggle = useWorldStore.getState().togglePermission;

           ["payments", "spend_auto"].forEach(pid => {
              const p = agent.permissions.find(x => x.id === pid);
              if (p && p.enabled !== enabled) toggle(agent.id, pid);
           });

           if (budget) {
             const newBudget = { ...budget, payments_enabled: enabled };
             setBudget(newBudget);
             try { await invoke('update_agent_budget', { budget: newBudget }); } catch (e) { console.error(e); }
           }

           setTimeout(async () => {
             const currentAgent = useWorldStore.getState().agents.find(a => a.id === agent.id);
             if (!currentAgent) return;
             const capabilitiesObj: any = {};
             currentAgent.permissions.forEach(px => capabilitiesObj[px.id] = px.enabled);
             try { await invoke("update_agent_capabilities", { agentId: agent.id, capabilities: capabilitiesObj }); } catch (e) { console.error(e); }
           }, 100);
        }}
      >
        <div style={{ display: "flex", flexDirection: "column", gap: 20 }}>
          {/* Permissions Toggles */}
          <div style={{ display: "flex", flexDirection: "column", gap: 16 }}>
            {agent.permissions.filter(p => ["payments", "spend_auto"].includes(p.id)).map((p, i, arr) => (
              <div key={p.id} style={{ display: "flex", justifyContent: "space-between", alignItems: "center", borderBottom: "1px solid rgba(0,0,0,0.04)", paddingBottom: 12 }}>
                <div>
                  <div style={{ fontSize: 13, fontWeight: 700, color: "var(--text-main)" }}>{p.label}</div>
                  <div style={{ fontSize: 11, color: "var(--text-sub)", marginTop: 4 }}>{p.description}</div>
                </div>
                <Toggle enabled={p.enabled} onChange={async () => {
                  const { invoke } = await import('@tauri-apps/api/core');
                  useWorldStore.getState().togglePermission(agent.id, p.id);
                  setTimeout(async () => {
                    const currentAgent = useWorldStore.getState().agents.find(a => a.id === agent.id);
                    if (!currentAgent) return;
                    const capabilitiesObj: any = {};
                    currentAgent.permissions.forEach(px => capabilitiesObj[px.id] = px.enabled);
                    try { await invoke("update_agent_capabilities", { agentId: agent.id, capabilities: capabilitiesObj }); } catch (e) { console.error(e); }
                  }, 100);
                }} />
              </div>
            ))}
          </div>

          {/* Budget UI */}
          {budgetLoading ? (
            <div style={{ fontSize: 12, color: "var(--text-sub)" }}>Loading budget data...</div>
          ) : !budget ? (
            <div style={{ fontSize: 12, color: "var(--text-sub)" }}>Failed to load budget data.</div>
          ) : (
            <>
              <div style={{ padding: 16, borderRadius: 12, background: "rgba(0,0,0,0.02)", border: "1px solid rgba(0,0,0,0.05)" }}>
                <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 20 }}>
                  <div style={{ fontSize: 14, fontWeight: 700, color: "var(--text-main)" }}>Virtual Card Access</div>
                  <Toggle enabled={budget.payments_enabled} onChange={() => updateBudgetProp("payments_enabled", !budget.payments_enabled)} />
                </div>
                <div style={{ fontSize: 12, color: "var(--text-sub)", marginBottom: 20 }}>When disabled, the agent cannot issue any real-world merchant charges. It will simulate approvals.</div>

                <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 12 }}>
                  <div style={{ fontSize: 12, fontWeight: 600, color: "var(--text-main)" }}>Require Approval for New Merchants</div>
                  <Toggle enabled={budget.require_approval_new_merchant} onChange={() => updateBudgetProp("require_approval_new_merchant", !budget.require_approval_new_merchant)} />
                </div>
                <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
                  <div style={{ fontSize: 12, fontWeight: 600, color: "var(--text-main)" }}>Require Approval for Subscriptions</div>
                  <Toggle enabled={budget.require_approval_recurring} onChange={() => updateBudgetProp("require_approval_recurring", !budget.require_approval_recurring)} />
                </div>
              </div>

              <div style={{ padding: 16, borderRadius: 12, background: "rgba(0,0,0,0.02)", border: "1px solid rgba(0,0,0,0.05)" }}>
                <div style={{ fontSize: 14, fontWeight: 700, color: "var(--text-main)", marginBottom: 20 }}>Limits & Thresholds</div>

                <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: 16 }}>
                  <div style={{ fontSize: 12, fontWeight: 600, color: "var(--text-main)" }}>Per-Transaction Limit ($)</div>
                  <input type="number" value={budget.per_transaction_limit_cents / 100} onChange={e => updateBudgetProp("per_transaction_limit_cents", Math.max(0, parseInt(e.target.value) || 0) * 100)} style={{ width: 90, padding: "6px 10px", borderRadius: 6, border: "1px solid rgba(0,0,0,0.1)", background: "var(--surface-card)", textAlign: "right", fontSize: 12 }} />
                </div>

                <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: 16 }}>
                  <div style={{ fontSize: 12, fontWeight: 600, color: "var(--text-main)" }}>Auto-Approve Threshold ($)</div>
                  <input type="number" value={budget.auto_approve_threshold_cents / 100} onChange={e => updateBudgetProp("auto_approve_threshold_cents", Math.max(0, parseInt(e.target.value) || 0) * 100)} style={{ width: 90, padding: "6px 10px", borderRadius: 6, border: "1px solid rgba(0,0,0,0.1)", background: "var(--surface-card)", textAlign: "right", fontSize: 12 }} />
                </div>

                <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: 16 }}>
                  <div style={{ fontSize: 12, fontWeight: 600, color: "var(--text-main)" }}>Daily Budget Total ($)</div>
                  <input type="number" value={budget.daily_limit_cents / 100} onChange={e => updateBudgetProp("daily_limit_cents", Math.max(0, parseInt(e.target.value) || 0) * 100)} style={{ width: 90, padding: "6px 10px", borderRadius: 6, border: "1px solid rgba(0,0,0,0.1)", background: "var(--surface-card)", textAlign: "right", fontSize: 12 }} />
                </div>

                <div style={{ display: "flex", justifyContent: "flex-end", marginTop: 8 }}>
                  <button onClick={handleSaveBudget} disabled={budgetSaving} style={{
                    padding: "8px 16px", borderRadius: 8, background: budgetSaving ? "#4A9E96" : "#3c6663", color: "var(--surface-card)", fontSize: 12, fontWeight: 600, border: "none", cursor: budgetSaving ? "default" : "pointer", transition: "0.2s"
                  }}>
                    {budgetSaving ? "Saved ✓" : "Commit Limits"}
                  </button>
                </div>
              </div>
            </>
          )}
        </div>
      </ServiceRow>

    </div>
  );
}

TerminalPane.text:
function TerminalPane({ agent, onClose }: { agent: AgentData; onClose: () => void }) {
  const [history, setHistory] = useState<{ command: string; output: string; timestamp: string }[]>([]);
  const [input, setInput] = useState("");
  const [running, setRunning] = useState(false);
  const endRef = useRef<HTMLDivElement>(null);

  // Auto-scroll to bottom
  useEffect(() => {
    endRef.current?.scrollIntoView({ behavior: "smooth" });
  }, [history]);

  useEffect(() => {
    const fetchAudit = async () => {
      try {
         const { invoke } = await import('@tauri-apps/api/core');
         const histText: any = await invoke('read_workspace_file', { agentId: agent.id, filename: '.terminal_history.json' }).catch(() => "[]");
         if (histText) {
             try {
                const parsed = JSON.parse(histText);
                if (Array.isArray(parsed)) setHistory(parsed);
             } catch (e) {}
         }
      } catch (e) { console.error(e); }
    };
    fetchAudit();
  }, [agent.id]);

  const saveHistory = async (newHist: any[]) => {
      try {
         const { invoke } = await import('@tauri-apps/api/core');
         await invoke('write_workspace_file', { agentId: agent.id, filename: '.terminal_history.json', content: JSON.stringify(newHist, null, 2) });
      } catch (e) {}
  };

  const executeCommand = async () => {
    if (!input.trim() || running) return;
    const cmd = input;
    setInput("");
    setRunning(true);

    let output = "";
    try {
       const { invoke } = await import('@tauri-apps/api/core');
       output = await invoke("run_agent_command", { agentId: agent.id, command: cmd });
    } catch (e: any) {
       output = String(e);
    }
    setRunning(false);

    try {
       const { invoke } = await import('@tauri-apps/api/core');
       const histText: any = await invoke('read_workspace_file', { agentId: agent.id, filename: '.terminal_history.json' }).catch(() => "[]");
       if (histText) {
           const parsed = JSON.parse(histText);
           if (Array.isArray(parsed)) setHistory(parsed);
       }
    } catch (e) { console.error(e); }
  };

  return (
    <div style={{ flex: 1, overflow: "hidden", display: "flex", flexDirection: "column", background: "#0a0a0a", borderRadius: 12, border: "1px solid rgba(255,255,255,0.1)", margin: "0 40px 32px 40px", position: "relative" }}>
      <div style={{ padding: "12px 16px", background: "rgba(255,255,255,0.05)", display: "flex", justifyContent: "space-between", alignItems: "center", borderBottom: "1px solid rgba(255,255,255,0.1)" }}>
        <div style={{ display: "flex", alignItems: "center", gap: 8, color: "white" }}>
          <Terminal size={16} />
          <span style={{ fontSize: 13, fontWeight: 600, fontFamily: "monospace" }}>{agent.name} / Workspace Terminal</span>
        </div>
        <button onClick={onClose} style={{ background: "none", border: "none", color: "rgba(255,255,255,0.5)", cursor: "pointer" }}>
          <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><path d="M18 6L6 18M6 6l12 12" /></svg>
        </button>
      </div>

      <div style={{ flex: 1, overflowY: "auto", padding: 16, fontFamily: "'Geist Mono', monospace", fontSize: 12, color: "#d4d4d4", display: "flex", flexDirection: "column", gap: 16 }}>
        {history.length === 0 && (
          <div style={{ opacity: 0.5, fontStyle: "italic", textAlign: "center", marginTop: 20 }}>No terminal history found.</div>
        )}
        {history.map((h, i) => (
          <div key={i} style={{ display: "flex", flexDirection: "column", gap: 4 }}>
            <div style={{ display: "flex", gap: 8, color: "#4ade80" }}>
              <span style={{ userSelect: "none" }}>$</span>
              <span style={{ fontWeight: 600, color: "white" }}>{h.command}</span>
            </div>
            {h.output && (
              <pre style={{ margin: 0, whiteSpace: "pre-wrap", background: "rgba(255,255,255,0.03)", padding: "8px 12px", borderRadius: 6, color: "#a3a3a3", border: "1px solid rgba(255,255,255,0.05)", overflowX: "auto" }}>
                {h.output.trim() || "(No output)"}
              </pre>
            )}
          </div>
        ))}
        <div ref={endRef} />
      </div>

      <div style={{ padding: 16, background: "rgba(0,0,0,0.2)", borderTop: "1px solid rgba(255,255,255,0.05)" }}>
        <div style={{ display: "flex", gap: 12, alignItems: "center" }}>
          <span style={{ color: "#4ade80", fontFamily: "'Geist Mono', monospace", fontWeight: 600 }}>$</span>
          <input 
            value={input}
            onChange={e => setInput(e.target.value)}
            onKeyDown={e => {
              if (e.key === 'Enter') executeCommand();
              if (e.key === 'ArrowUp' && history.length > 0) setInput(history[history.length - 1].command);
            }}
            placeholder="Type a bash command to run in the agent's workspace..."
            style={{ flex: 1, background: "transparent", border: "none", color: "white", fontFamily: "'Geist Mono', monospace", fontSize: 13, outline: "none" }}
            disabled={running}
            autoFocus
          />
          <button 
            onClick={executeCommand}
            disabled={!input.trim() || running}
            style={{ padding: "6px 12px", background: running ? "rgba(255,255,255,0.1)" : "#218380", color: "white", border: "none", borderRadius: 6, fontSize: 12, fontWeight: 600, cursor: input.trim() && !running ? "pointer" : "default", opacity: input.trim() || running ? 1 : 0.5 }}
          >
            {running ? "Running..." : "Run"}
          </button>
        </div>
      </div>
    </div>
  );
}

OverviewTab.text:
// ─── Overview Tab ────────────────────────────────────────────────────────────

function OverviewTab({ agent, onUpdate, onNavigate }: { agent: AgentData; onUpdate?: () => void; onNavigate?: (tab: string) => void }) {
  const gatewayReady = useWorldStore(s => s.gatewayReady);
  const [repairLog, setRepairLog] = useState<string | null>(null);
  const [repairSucceeded, setRepairSucceeded] = useState<boolean | null>(null);
  const [hardResetting, setHardResetting] = useState(false);

  const [isEditingDetails, setIsEditingDetails] = useState(false);
  const [tempName, setTempName] = useState(agent.name);
  const [tempRole, setTempRole] = useState(agent.role);
  const [recentLogs, setRecentLogs] = useState<any[]>([]);
  const [webLoginsExpanded, setWebLoginsExpanded] = useState(false);

  useEffect(() => {
    setIsEditingDetails(false);
    setTempName(agent.name);
    setTempRole(agent.role);

    // Fetch recent audit logs (which now includes chats)
    const fetchLogs = async () => {
      try {
        const { invoke } = await import('@tauri-apps/api/core');
        const data: any = await invoke('get_global_audit_log', { limit: 100, agentId: agent.id });
        setRecentLogs(Array.isArray(data) ? data : []);
      } catch (e) {
        console.error("Failed to fetch recent audit log", e);
      }
    };
    fetchLogs();
  }, [agent.id]);

  const saveDetails = async () => {
    if (!tempName.trim()) return;
    try {
      const { invoke } = await import('@tauri-apps/api/core');
      await invoke("update_agent_details", {
        agentId: agent.id,
        name: tempName,
        role: tempRole
      });
      // Update global store
      const { setAgents, agents } = useWorldStore.getState();
      setAgents(agents.map(a => a.id === agent.id ? { ...a, name: tempName, role: tempRole } : a));
      setIsEditingDetails(false);
      if (tempName !== agent.name && onUpdate) {
        onUpdate();
      }
    } catch (e) {
      console.error("Failed to update agent details:", e);
    }
  };

  const handleHardReset = async () => {
    setHardResetting(true);
    setRepairLog("Hard Reset in progress...\n\nRestarting OrbStack Linux VM and rebuilding the gateway container.\nThis takes 15–20 seconds.");
    setRepairSucceeded(null);
    try {
      await invoke("hard_reset_infrastructure");
      setRepairLog("✓ Hard Reset complete — OrbStack VM restarted. Re-registering agents...");
      // Re-run boot_sync_agents so agents are registered and credentials written
      // after the container comes back up. Without this, agents.list is restored
      // but no auth-profiles.json is written and the gateway can't authenticate.
      try {
        await invoke("boot_sync_agents");
        setRepairLog("✓ Hard Reset complete — gateway restarted and agents re-initialized.");
      } catch (syncErr) {
        console.warn("boot_sync after hard reset:", syncErr);
        setRepairLog("✓ Hard Reset complete — gateway restarted.\n(Agent re-sync ran in background.)");
      }
      setRepairSucceeded(true);
    } catch (e) {
      setRepairLog(`✗ Hard Reset failed:\n${String(e)}\n\nMake sure OrbStack is installed and try opening it manually.`);
      setRepairSucceeded(false);
    }
    setHardResetting(false);
  };

  return (
    <div>
      {agent.paused && (
        <div style={{ background: "var(--surface-base)", border: "1px solid var(--border-subtle)", borderRadius: 16, padding: 24, marginBottom: 32 }}>
          <div style={{ display: "flex", gap: 20, alignItems: "center" }}>
            <div style={{ width: 48, height: 48, borderRadius: "50%", background: "var(--text-muted)", display: "flex", alignItems: "center", justifyContent: "center", color: "white", flexShrink: 0 }}>
              <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><rect x="6" y="4" width="4" height="16"/><rect x="14" y="4" width="4" height="16"/></svg>
            </div>
            <div style={{ flex: 1 }}>
              <div style={{ fontSize: 16, fontWeight: 700, color: "var(--text-main)", marginBottom: 4 }}>Agent Paused</div>
              <div style={{ fontSize: 13, color: "var(--text-sub)" }}>This agent won't load into the gateway at startup. Use "▶ Resume Agent" in the Danger Zone to re-activate it.</div>
            </div>
          </div>
        </div>
      )}
      {agent.status === "error" && !agent.paused && !gatewayReady && (
        <div style={{ background: "#fffbf0", border: "1px solid #f4d58a", borderRadius: 16, padding: 24, marginBottom: 32 }}>
          <div style={{ display: "flex", gap: 20, alignItems: "center" }}>
            <div style={{ width: 48, height: 48, borderRadius: "50%", background: "#F4A83A", display: "flex", alignItems: "center", justifyContent: "center", color: "white", flexShrink: 0 }}>
              <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><circle cx="12" cy="12" r="10"/><polyline points="12 6 12 12 16 14"/></svg>
            </div>
            <div style={{ flex: 1 }}>
              <div style={{ fontSize: 16, fontWeight: 700, color: "var(--text-main)", marginBottom: 4 }}>Agent is Waking Up</div>
              <div style={{ fontSize: 13, color: "var(--text-sub)" }}>The gateway is still starting. This takes up to 90 seconds on a cold start — hang tight.</div>
            </div>
          </div>
        </div>
      )}
      {agent.status === "error" && !agent.paused && gatewayReady && (
        <div style={{ background: "#fcf3f3", border: "1px solid #f2bdbd", borderRadius: 16, padding: 24, marginBottom: 32 }}>
          <div style={{ display: "flex", gap: 20, alignItems: "center" }}>
            <div style={{ width: 48, height: 48, borderRadius: "50%", background: "#E57373", display: "flex", alignItems: "center", justifyContent: "center", color: "var(--surface-card)", flexShrink: 0 }}>
              <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><circle cx="12" cy="12" r="10"></circle><line x1="12" y1="8" x2="12" y2="12"></line><line x1="12" y1="16" x2="12.01" y2="16"></line></svg>
            </div>
            <div style={{ flex: 1 }}>
              <div style={{ fontSize: 16, fontWeight: 700, color: "var(--text-main)", marginBottom: 4 }}>Agent Environment Offline</div>
              <div style={{ fontSize: 13, color: "var(--text-sub)" }}>The OpenClaw setup failed or the local Docker container unexpectedly stopped.</div>
            </div>
            <div style={{ display: "flex", gap: 8 }}>
              <button
                onClick={handleHardReset}
                disabled={hardResetting}
                title="Restart OrbStack VM and rebuild the gateway container from scratch"
                style={{ padding: "10px 16px", borderRadius: 10, background: "transparent", color: "#E57373", fontSize: 12, fontWeight: 600, border: "1px solid #E57373", cursor: hardResetting ? "not-allowed" : "pointer", opacity: hardResetting ? 0.6 : 1, transition: "all 0.2s ease", whiteSpace: "nowrap" }}>
                {hardResetting ? "Resetting..." : "Hard Reset"}
              </button>
              <button
                id="repair-openclaw-btn"
                onClick={async () => {
                  const btn = document.getElementById('repair-openclaw-btn');
                  if (btn) btn.innerText = "Rebuilding...";
                  setRepairLog(null);
                  setRepairSucceeded(null);
                  try {
                    if (typeof invoke === 'function') {
                      // Per-agent key takes priority; global key is the fallback.
                      const agAnthropic = String(await invoke("get_secret_cmd", { key: `agent_${agent.id}_anthropic_key` }).catch(() => "") || "")
                                       || String(await invoke("get_secret_cmd", { key: "ANTHROPIC_API_KEY" }).catch(() => "") || "");
                      const agOpenAI    = String(await invoke("get_secret_cmd", { key: `agent_${agent.id}_openai_key` }).catch(() => "") || "")
                                       || String(await invoke("get_secret_cmd", { key: "OPENAI_API_KEY" }).catch(() => "") || "");
                      const agGemini    = String(await invoke("get_secret_cmd", { key: `agent_${agent.id}_gemini_key` }).catch(() => "") || "")
                                       || String(await invoke("get_secret_cmd", { key: "GEMINI_API_KEY" }).catch(() => "") || "");
                      const agGrok      = String(await invoke("get_secret_cmd", { key: `agent_${agent.id}_grok_key` }).catch(() => "") || "")
                                       || String(await invoke("get_secret_cmd", { key: "XAI_API_KEY" }).catch(() => "")
                                       || await invoke("get_secret_cmd", { key: "GROK_API_KEY" }).catch(() => "") || "");

                      await invoke("sync_credentials", {
                        agentId: agent.id, keys: {
                          "ANTHROPIC_API_KEY": agAnthropic,
                          "OPENAI_API_KEY":    agOpenAI,
                          "GEMINI_API_KEY":    agGemini,
                          "XAI_API_KEY":       agGrok,
                        }
                      }).catch((err) => console.error("Sync credentials failed:", err));

                      const res = await invoke("repair_gateway", { agentId: agent.id });
                      if (btn) btn.innerText = "Repaired!";
                      setRepairLog(String(res));
                      setRepairSucceeded(true);

                      // Clear the error status — the agent is now registered and live.
                      useWorldStore.setState(state => ({
                        agents: state.agents.map(a => a.id === agent.id
                          ? { ...a, status: "active", currentAction: "idle" }
                          : a)
                      }));
                    }
                  } catch (e) {
                    if (btn) btn.innerText = "Failed — See Details";
                    setRepairLog(String(e));
                    setRepairSucceeded(false);
                    console.error("Openclaw repair failed:", e);
                  }
                  setTimeout(() => { if (btn) btn.innerText = "Re-Initialize Setup"; }, 3000);
                }}
                style={{ padding: "10px 20px", borderRadius: 10, background: "#E57373", color: "var(--surface-card)", fontSize: 13, fontWeight: 600, border: "none", cursor: "pointer", transition: "all 0.2s ease", whiteSpace: "nowrap" }}>
                Re-Initialize Setup
              </button>
            </div>
          </div>
          {repairLog && (
            <div style={{
              padding: 16,
              borderRadius: 12,
              background: repairSucceeded === true ? "rgba(52,211,153,0.07)" : repairSucceeded === false ? "rgba(229,115,115,0.08)" : "rgba(0,0,0,0.04)",
              border: `1px solid ${repairSucceeded === true ? "rgba(52,211,153,0.25)" : repairSucceeded === false ? "rgba(229,115,115,0.3)" : "rgba(0,0,0,0.1)"}`,
              color: repairSucceeded === true ? "#1a6b52" : repairSucceeded === false ? "#c62828" : "var(--text-sub)",
              fontSize: 11,
              marginTop: 20,
              whiteSpace: "pre-wrap",
              fontFamily: "'Geist Mono', monospace",
              maxHeight: 260,
              overflowY: "auto",
              lineHeight: 1.6,
            }}>
              {repairLog}
            </div>
          )}
        </div>
      )}

      {/* Header */}
      <div style={{ marginBottom: 32, display: "flex", justifyContent: "space-between", alignItems: "center", background: "var(--surface-card)", padding: 24, borderRadius: 20, border: "1px solid var(--border-subtle)", boxShadow: "0 4px 20px rgba(0,0,0,0.03)" }}>
        <div style={{ display: "flex", gap: 20, alignItems: "center" }}>
          <div style={{ width: 72, height: 72, borderRadius: "50%", display: "flex", alignItems: "center", justifyContent: "center", background: `${agent.robeColor || "#CCC"}15`, boxShadow: `0 0 0 1px ${agent.robeColor || "#CCC"}40`, flexShrink: 0 }}>
            <LobsterIcon size={72} role={agent.role} agentImage={agent.image} shellColor={agent.robeColor} accentColor={agent.accentColor} />
          </div>
          <div>
            {isEditingDetails ? (
              <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
                <input value={tempName} onChange={e => setTempName(e.target.value)} style={{ fontSize: 24, fontWeight: 700, padding: "4px 8px", borderRadius: 8, border: "1px solid rgba(0,0,0,0.1)", background: "var(--surface-base)", outline: "none", color: "var(--text-main)" }} />
                <input value={tempRole} onChange={e => setTempRole(e.target.value)} style={{ fontSize: 14, padding: "4px 8px", borderRadius: 8, border: "1px solid rgba(0,0,0,0.1)", background: "var(--surface-base)", outline: "none", color: "var(--text-sub)" }} />
                <div style={{ display: "flex", gap: 8, marginTop: 4 }}>
                  <button onClick={saveDetails} style={{ padding: "6px 16px", background: "#4A9E96", color: "white", borderRadius: 8, border: "none", cursor: "pointer", fontSize: 12, fontWeight: 600 }}>Save</button>
                  <button onClick={() => { setIsEditingDetails(false); setTempName(agent.name); setTempRole(agent.role); }} style={{ padding: "6px 16px", background: "transparent", color: "var(--text-sub)", border: "1px solid var(--border-subtle)", borderRadius: 8, cursor: "pointer", fontSize: 12 }}>Cancel</button>
                </div>
              </div>
            ) : (
              <>
                <div style={{ display: "flex", alignItems: "baseline", gap: 8 }}>
                  <h1 style={{ fontSize: 28, fontWeight: 700, color: "var(--text-main)", letterSpacing: "-0.01em", margin: 0, lineHeight: 1.1 }}>
                    {agent.name}
                  </h1>
                  <div style={{ fontSize: 16, color: "var(--text-sub)", fontWeight: 500 }}>{agent.title}</div>
                </div>
                <p style={{ fontSize: 14, color: "var(--text-sub)", marginTop: 6, maxWidth: 600, lineHeight: 1.5 }}>
                  {agent.description}
                </p>
              </>
            )}
          </div>
        </div>
        <button onClick={() => setIsEditingDetails(true)} style={{ display: "flex", alignItems: "center", gap: 8, padding: "8px 16px", background: "var(--surface-base)", border: "1px solid var(--border-subtle)", borderRadius: 12, cursor: "pointer", color: "var(--text-sub)", fontSize: 13, fontWeight: 600 }}>
          <Edit2 size={16} />
          Edit Agent
        </button>
      </div>

      {/* Side-by-side: 3D View and Chat */}
      <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 16, marginBottom: 24, minHeight: 400 }}>
        {/* 3D Lobster View */}
        <div style={{ background: "var(--surface-card)", border: "1px solid var(--border-subtle)", borderRadius: 16, position: "relative", overflow: "hidden" }}>
          <Canvas orthographic camera={{ position: [10, 10, 10], zoom: 60 }}>
            <ambientLight intensity={0.8} color="#F5E6D8" />
            <directionalLight position={[10, 20, 5]} intensity={1} />
            <OrbitControls enablePan={false} enableZoom={false} />
            <group position={[0, -0.6, 0]}>
              <GLBAgent
                fileUrl={["Accountant", "Assistant", "Strategist", "Researcher", "Tutor", "Coder"].includes(agent.role) ? `/models/lobsters/${agent.role}.glb` : undefined}
                accessories={agent.visual_identity?.accessories || []}
                agentStatus={agent.status}
                scale={1.0}
                robeColor={agent.color || agent.robeColor}
                forceAnimation="none"
              />
              <React.Suspense fallback={null}>
                {(agent.visual_identity?.accessories || []).map((path, i) => (
                  <SafeBillboard
                    key={i}
                    url={path}
                    position={[
                      0.5 * Math.cos(i * Math.PI * 2 / (agent.visual_identity?.accessories?.length || 1)),
                      0.2 + 0.3 * Math.sin(i * Math.PI * 2 / (agent.visual_identity?.accessories?.length || 1)),
                      0.5 * Math.sin(i * Math.PI * 2 / (agent.visual_identity?.accessories?.length || 1))
                    ]}
                  />
                ))}
              </React.Suspense>
            </group>
          </Canvas>
        </div>

        {/* Chat Box */}
        <div style={{ background: "var(--surface-card)", border: "1px solid var(--border-subtle)", borderRadius: 16, display: "flex", flexDirection: "column", height: 400, overflow: "hidden" }}>
          <ChatTab agent={agent} compact={true} />
        </div>
      </div>

      {/* Status + Stats row */}
      <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr 1fr", gap: 16, marginBottom: 24 }}>
        <div style={{ ...glass(0.5), padding: 20, borderRadius: 16 }}>
          <div style={{ fontSize: 10, fontWeight: 600, letterSpacing: "0.06em", color: "var(--text-sub)", textTransform: "uppercase", marginBottom: 8 }}>Current State</div>
          <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
            <div style={{
              width: 10, height: 10, borderRadius: "50%",
              background: agent.paused ? "var(--text-muted)" : !gatewayReady ? "#F4A83A" : agent.status === "active" ? "#4A9E96" : agent.status === "thinking" ? "#8B6AAE" : agent.status === "error" ? "#E57373" : "var(--text-muted)",
              boxShadow: agent.paused ? "none" : !gatewayReady ? "0 0 8px rgba(244,168,58,0.5)" : agent.status === "active" ? "0 0 8px rgba(74,158,150,0.5)" : agent.status === "error" ? "0 0 8px rgba(229,115,115,0.5)" : "none",
              animation: (!agent.paused && !gatewayReady) ? "pulse 1.5s ease-in-out infinite" : "none",
            }} />
            <span style={{ fontSize: 20, fontWeight: 600, color: agent.paused ? "var(--text-muted)" : !gatewayReady ? "#F4A83A" : "var(--text-main)", textTransform: "capitalize" }}>
              {agent.paused ? "Paused" : !gatewayReady ? "Waking Up" : agent.status === "error" ? "Offline" : agent.currentAction}
            </span>
          </div>
          <div style={{ display: "flex", justifyContent: "space-between", marginTop: 12, fontSize: 11, color: "var(--text-sub)" }}>
            <span>Uptime</span>
            <span style={{ fontWeight: 500, color: "var(--text-main)" }}>{agent.uptime}</span>
          </div>
        </div>

        <div style={{ ...glass(0.5), padding: 20, borderRadius: 16 }}>
          <div style={{ fontSize: 10, fontWeight: 600, letterSpacing: "0.06em", color: "var(--text-sub)", textTransform: "uppercase", marginBottom: 8 }}>Resource Consumption</div>
          <div style={{ display: "flex", justifyContent: "space-between", marginBottom: 12 }}>
            <div>
              <div style={{ fontSize: 10, color: "var(--text-sub)" }}>Weekly Compute</div>
              <div style={{ fontSize: 20, fontWeight: 600, color: "var(--text-main)" }}>{agent.weeklyCompute}</div>
            </div>
            <div>
              <div style={{ fontSize: 10, color: "var(--text-sub)" }}>Tokens Used</div>
              <div style={{ fontSize: 20, fontWeight: 600, color: "var(--text-main)" }}>
                {(() => {
                  const totalTokens = (agent.stats?.total_tokens_in || 0) + (agent.stats?.total_tokens_out || 0);
                  if (totalTokens === 0) return agent.tokensUsed || "0k";
                  if (totalTokens > 1000000) return (totalTokens / 1000000).toFixed(1) + "M";
                  if (totalTokens > 1000) return (totalTokens / 1000).toFixed(1) + "k";
                  return totalTokens;
                })()}
              </div>
            </div>
          </div>
          <ProgressBar value={parseFloat(agent.weeklyCompute)} max={0.1} color="#4A9E96" />
        </div>

        <div style={{ ...glass(0.5), padding: 20, borderRadius: 16 }}>
          <div style={{ fontSize: 10, fontWeight: 600, letterSpacing: "0.06em", color: "var(--text-sub)", textTransform: "uppercase", marginBottom: 8 }}>Cost (Active)</div>
          <div style={{ fontSize: 28, fontWeight: 700, color: "var(--text-main)" }}>${(agent.stats?.total_cost_usd || agent.monthlySpend || 0).toFixed(2)}</div>
          <div style={{ fontSize: 11, color: "var(--text-sub)", marginBottom: 8 }}>of ${agent.spendLimit} limit</div>
          <ProgressBar value={agent.stats?.total_cost_usd || agent.monthlySpend || 0} max={agent.spendLimit} color={(agent.stats?.total_cost_usd || agent.monthlySpend || 0) > agent.spendLimit * 0.8 ? "#D4A04A" : "#4A9E96"} />
        </div>
      </div>

      {/* Access Level + Recent History */}
      <div style={{ display: "grid", gridTemplateColumns: "1fr 1.5fr", gap: 16, marginBottom: 32 }}>
        {/* Access Level */}
        <div style={{ ...glass(0.5), padding: 24, borderRadius: 16, display: "flex", flexDirection: "column", alignItems: "center", textAlign: "center", position: "relative" }}>
          {(() => {
            const hasYolo = agent.permissions.some(p => ["autonomous", "spend_auto"].includes(p.id) && p.enabled);
            const hasSecure = agent.permissions.some(p => ["ext_network", "file_write", "payments", "imessage", "photos"].includes(p.id) && p.enabled);
            const enabledPerms = agent.permissions.filter(p => p.enabled);

            let stateLabel = "Locked Down";
            let temperatureLevel = 0;
            let iconColor = "#22c55e";

            if (hasYolo) {
              stateLabel = "YOLO Mode (High Risk ⚠️)";
              temperatureLevel = 2;
              iconColor = "#ef4444";
            } else if (hasSecure) {
              stateLabel = "Secure";
              temperatureLevel = 1;
              iconColor = "#f59e0b";
            }

            return (
              <>
                <div style={{ position: "absolute", top: 16, right: 16 }}>
                  <button onClick={() => onNavigate?.("permissions")} style={{ padding: "4px 10px", borderRadius: 6, border: "1px solid var(--border-subtle)", background: "var(--surface-base)", cursor: "pointer", fontSize: 11, fontWeight: 600, color: "var(--text-sub)" }}>Edit</button>
                </div>
                <div style={{ display: "flex", flexDirection: "column", alignItems: "center", marginBottom: 16, width: "100%", maxWidth: 180 }}>
                  <div style={{ width: 32, height: 32, borderRadius: "50%", background: "var(--surface-base)", display: "flex", alignItems: "center", justifyContent: "center", marginBottom: 8 }}>
                    <Lock size={16} color={iconColor} strokeWidth={2.5} />
                  </div>
                  <div style={{ fontSize: 14, fontWeight: 700, color: "var(--text-main)", marginBottom: 8 }}>{stateLabel}</div>
                  <div style={{ position: "relative", width: "100%", height: 6, background: "linear-gradient(to right, #22c55e, #f59e0b, #ef4444)", borderRadius: 3 }}>
                    <div style={{ position: "absolute", top: -3, left: `${temperatureLevel * 50}%`, width: 12, height: 12, borderRadius: "50%", background: "#fff", border: "2px solid #333", transform: "translateX(-50%)", transition: "left 0.3s" }} />
                  </div>
                </div>

                <div style={{ fontSize: 11, fontWeight: 600, color: "var(--text-sub)", alignSelf: "flex-start", marginBottom: 8, textTransform: "uppercase", letterSpacing: "0.04em" }}>Enabled Permissions & Connectors</div>
                <div style={{ display: "flex", flexDirection: "column", gap: 6, width: "100%", flex: 1, overflowY: "auto", paddingRight: 4 }}>
                  {enabledPerms.length === 0 && (!agent.integrations || agent.integrations.length === 0) && <div style={{ fontSize: 12, color: "var(--text-muted)" }}>No permissions enabled.</div>}
                  {enabledPerms.map(p => {
                    const desc = p.description || "Core permission";
                    const isRecommended = DEFAULT_PERMISSIONS.find(dp => dp.id === p.id)?.enabled !== false;
                    return (
                      <div key={p.id} style={{ display: "flex", alignItems: "center", justifyContent: "space-between", padding: "8px 12px", background: "var(--surface-base)", border: "1px solid var(--border-subtle)", borderRadius: 6, fontSize: 12, color: "var(--text-main)", textAlign: "left" }}>
                        <div><span style={{ color: "var(--text-sub)", marginRight: 6, fontWeight: 600 }}>Core:</span> {p.label}</div>
                        <div title={desc} style={{ cursor: "help", display: "flex", alignItems: "center" }}>
                          {isRecommended ? <CheckCircle2 size={14} color="#4A9E96" /> : <AlertTriangle size={14} color="#D4A04A" />}
                        </div>
                      </div>
                    );
                  })}
                  {(() => {
                     if (!agent.integrations) return null;

                     const normalIntegrations = agent.integrations.filter(intg => !intg.startsWith('web_'));
                     const webIntegrations = agent.integrations.filter(intg => intg.startsWith('web_'));

                     return (
                        <>
                           {normalIntegrations.map(intg => {
                              const names: Record<string, string> = { "slack": "Slack", "github": "GitHub", "gmail": "Gmail", "cal": "Google Calendar", "telegram": "Telegram", "discord": "Discord", "drive": "Google Drive", "passwords": "Web Vault" };
                              const label = names[intg] || intg;
                              return (
                               <div key={intg} style={{ display: "flex", alignItems: "center", justifyContent: "space-between", padding: "8px 12px", background: "var(--surface-base)", border: "1px solid var(--border-subtle)", borderRadius: 6, fontSize: 12, color: "var(--text-main)", textAlign: "left" }}>
                                 <div><span style={{ color: "#4A9E96", marginRight: 6, fontWeight: 600 }}>Bridge:</span> {label}</div>
                                 <div title={`Active connector: ${label}`} style={{ cursor: "help", display: "flex", alignItems: "center" }}>
                                   <CheckCircle2 size={14} color="#4A9E96" />
                                 </div>
                               </div>
                              );
                           })}
                           {webIntegrations.length > 0 && (
                              <div style={{ display: "flex", flexDirection: "column", background: "var(--surface-base)", border: "1px solid var(--border-subtle)", borderRadius: 6, overflow: "hidden" }}>
                                 <div 
                                    onClick={() => setWebLoginsExpanded(!webLoginsExpanded)}
                                    style={{ display: "flex", alignItems: "center", justifyContent: "space-between", padding: "8px 12px", cursor: "pointer", fontSize: 12, color: "var(--text-main)", textAlign: "left", userSelect: "none" }}
                                 >
                                    <div><span style={{ color: "#4A9E96", marginRight: 6, fontWeight: 600 }}>Bridge:</span> Web Vault Logins ({webIntegrations.length})</div>
                                    <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
                                       <div title={`Provides seamless login access to ${webIntegrations.length} sites`} style={{ cursor: "help", display: "flex", alignItems: "center" }}>
                                          <CheckCircle2 size={14} color="#4A9E96" />
                                       </div>
                                       {webLoginsExpanded ? <ChevronUp size={14} color="var(--text-sub)" /> : <ChevronDown size={14} color="var(--text-sub)" />}
                                    </div>
                                 </div>
                                 {webLoginsExpanded && (
                                    <div style={{ padding: "0 12px 8px 12px", display: "flex", flexDirection: "column", gap: 4 }}>
                                       {webIntegrations.map(intg => (
                                          <div key={intg} style={{ fontSize: 11, color: "var(--text-sub)", padding: "4px 8px", background: "rgba(0,0,0,0.03)", borderRadius: 4 }}>
                                             {intg.replace('web_', '')}
                                          </div>
                                       ))}
                                    </div>
                                 )}
                              </div>
                           )}
                        </>
                     );
                  })()}
                </div>
              </>
            );
          })()}
        </div>

        {/* Activity Infographic */}
        <div style={{ ...glass(0.5), padding: 24, borderRadius: 16, display: "flex", flexDirection: "column" }}>
          <div style={{ fontSize: 12, fontWeight: 600, letterSpacing: "0.06em", color: "var(--text-sub)", textTransform: "uppercase", marginBottom: 16 }}>Activity Patterns</div>
          {(() => {
             const hours = new Array(24).fill(0);
             if (recentLogs && recentLogs.length > 0) {
               recentLogs.forEach((log: any) => {
                 const h = new Date(log.timestamp).getHours();
                 hours[h] += 1;
               });
             } else {
               for(let i=0; i<24; i++) hours[i] = Math.floor(Math.random() * 3);
               hours[9] += 3; hours[14] += 4; hours[20] += 2;
             }
             const max = Math.max(...hours, 4);

             return (
               <div style={{ flex: 1, display: "flex", flexDirection: "column" }}>
                 <div style={{ flex: 1, display: "flex", alignItems: "flex-end", gap: 4, minHeight: 120, paddingBottom: 8, borderBottom: "1px solid var(--border-subtle)" }}>
                   {hours.map((val, i) => {
                     const heightPct = Math.max((val / max) * 100, 4);
                     return (
                       <div key={i} style={{ flex: 1, display: "flex", flexDirection: "column", justifyContent: "flex-end", height: "100%" }}>
                         <div style={{ width: "100%", height: `${heightPct}%`, background: val > 0 ? "var(--accent)" : "var(--glass-light)", opacity: val > 0 ? 0.8 : 0.3, borderRadius: "3px 3px 0 0", transition: "height 0.5s ease-out" }} title={`${val} actions at ${i}:00`} />
                       </div>
                     );
                   })}
                 </div>
                 <div style={{ display: "flex", justifyContent: "space-between", marginTop: 8, fontSize: 10, color: "var(--text-muted)", fontWeight: 600 }}>
                   <span>12 AM</span>
                   <span>12 PM</span>
                   <span>11 PM</span>
                 </div>
               </div>
             );
          })()}
          <button 
             onClick={() => onNavigate && onNavigate("activity")}
             style={{ width: "100%", padding: "12px", borderRadius: 8, background: "#3c6663", color: "white", fontWeight: 600, border: "none", cursor: "pointer", fontSize: 13, marginTop: 16 }}>
            View Activity Feed
          </button>
        </div>
      </div>
    </div>
  );
}

IdentityTab.text:
function IdentityTab({ agent }: { agent: AgentData }) {
  const { setAgents } = useWorldStore();
  const [accessorySearch, setAccessorySearch] = useState("");
  const [stagedVisuals, setStagedVisuals] = useState<Partial<AgentData["visual_identity"]>>(agent.visual_identity || {});

  useEffect(() => {
    setStagedVisuals(agent.visual_identity || {});
  }, [agent.id, agent.visual_identity]);

  const handleUpdateStaged = (updates: Partial<AgentData["visual_identity"]>) => {
    setStagedVisuals(prev => ({ ...prev, ...updates }));
  };

  const handleSave = async () => {
    const updatedVi = { ...stagedVisuals };
    setAgents(useWorldStore.getState().agents.map(a =>
      a.id === agent.id ? { ...a, color: updatedVi.color || a.color, robeColor: updatedVi.color || a.robeColor, accentColor: updatedVi.color || a.accentColor, visual_identity: updatedVi } as unknown as AgentData : a
    ));
    if (typeof invoke === 'function') {
      try {
        await invoke("update_agent_visuals", { agentId: agent.id, visualIdentity: updatedVi });
      } catch (e) {
        console.error("Failed to save visual identity", e);
      }
    }
  };

  const handleUndo = () => {
    setStagedVisuals(agent.visual_identity || {});
  };

  const hasChanges = JSON.stringify(stagedVisuals) !== JSON.stringify(agent.visual_identity || {});

  const handleApplyGeneration = (res: GenerativeResult) => {
    setAgents(useWorldStore.getState().agents.map(a =>
      a.id === agent.id ? {
        ...a,
        image: res.compiledImageUrl,
        color: res.dynamicParams.color || a.color,
        robeColor: res.dynamicParams.robeColor || a.robeColor,
        accentColor: res.dynamicParams.accentColor || a.accentColor,
        visual_identity: { ...a.visual_identity, accessories: [...(a.visual_identity?.accessories || []), ...res.dynamicParams.accessories] }
      } : a
    ));
  };

  const [catalog, setCatalog] = useState<any>(null);
  useEffect(() => {
    fetch('http://localhost:3001/api/accessories')
      .then(r => r.json())
      .then(d => setCatalog(d))
      .catch(() => { });
  }, []);

  const [habitats, setHabitats] = useState<any[]>([]);
  useEffect(() => {
    fetch('http://localhost:3001/api/habitats')
      .then(r => r.json())
      .then(d => setHabitats(d))
      .catch(() => { });
  }, []);

  const selectedHabitat = habitats.find(h => h.id === (stagedVisuals?.habitatId || agent.visual_identity?.habitatId || 1));
  const placement = selectedHabitat?.placement || { x: 0, y: 0, z: 0, rotationY: 0 };

  const visibleAccessories = React.useMemo(() => {
    if (!catalog || !catalog.items) return ACCESSORIES;
    return ACCESSORIES.filter(path => {
      if (catalog.items[path] && catalog.items[path].isVisible === false) return false;
      return true;
    });
  }, [catalog]);

  const sortedAccessories = useMemo(() => {
    const copy = [...visibleAccessories];
    const seed = agent.role.charCodeAt(0) % 6;
    const suggestions = copy.splice(seed * 25, 5);
    const combined = [...suggestions, ...copy];
    if (!accessorySearch) return combined;
    return combined.filter(a => a.toLowerCase().includes(accessorySearch.toLowerCase()));
  }, [agent.role, accessorySearch]);

  return (
    <div style={{ display: "flex", flexDirection: "column", gap: 32, height: "100%", paddingRight: 8 }}>
      {/* 3D Dressing Room Areas */}
      <div style={{ display: "flex", flexDirection: "column", gap: 16 }}>

        {/* Area 1: Base Lobster & Accessories */}
        <div style={{ background: "var(--glass-light)", borderRadius: 24, overflow: "hidden", position: "relative", flex: 2, border: "1px solid rgba(0,0,0,0.06)", minHeight: 400 }}>
          <Canvas orthographic camera={{ position: [10, 10, 10], zoom: 60 }}>
            <ambientLight intensity={0.8} color="#F5E6D8" />
            <directionalLight position={[10, 20, 5]} intensity={1} />
            <OrbitControls enablePan={false} />
            <group position={[0, -0.6, 0]}>
              <React.Suspense fallback={null}>
                <group 
                  position={[-placement.x * 10.0, (-0.1 - placement.y) * 10.0, -placement.z * 10.0]} 
                  scale={10.0} 
                  rotation={[0, Math.PI / 4 - (placement.rotationY * Math.PI / 180), 0]}
                >
                  <TerrariumBase 
                    habitatId={selectedHabitat?.id || stagedVisuals?.habitatId || agent.visual_identity?.habitatId || 1} 
                    modelUrl={selectedHabitat?.path} 
                  />
                </group>
              </React.Suspense>
              <GLBAgent
                fileUrl={stagedVisuals?.baseModelUrl || (["Accountant", "Assistant", "Strategist", "Researcher", "Tutor", "Coder"].includes(agent.role) ? `/models/lobsters/${agent.role}.glb` : undefined)}
                accessories={stagedVisuals?.accessories || []}
                agentStatus={agent.status}
                scale={1.0}
                robeColor={stagedVisuals?.color || agent.color}
                forceAnimation="none"
              />
              {/* Fallback Accessory Stickers for Preview */}
              <React.Suspense fallback={null}>
                {(stagedVisuals?.accessories || []).map((path, i) => (
                  <SafeBillboard
                    key={path}
                    url={`http://localhost:3001${path}`}
                    position={[(i - ((stagedVisuals?.accessories?.length || 1) - 1) / 2) * 1.2, 2.5, 0]}
                  />
                ))}
              </React.Suspense>
            </group>
          </Canvas>
          <div style={{ position: "absolute", top: 16, left: 16, background: "var(--glass-heavy)", padding: "6px 12px", borderRadius: 20, fontSize: 11, fontWeight: 700, color: "#218380", display: "flex", alignItems: "center", gap: 6 }}>
            <span style={{ width: 6, height: 6, borderRadius: "50%", background: "#218380", animation: "pulse 2s infinite" }} />
            Core Agent
          </div>
          {hasChanges && (
            <div style={{ position: "absolute", top: 16, right: 16, display: "flex", gap: 8 }}>
              <button
                onClick={handleUndo}
                style={{ background: "rgba(0,0,0,0.05)", border: "none", padding: "6px 12px", borderRadius: 20, fontSize: 11, fontWeight: 700, color: "var(--text-sub)", cursor: "pointer", transition: "all 0.2s" }}
              >
                Undo
              </button>
              <button
                onClick={handleSave}
                style={{ background: "#218380", border: "none", padding: "6px 12px", borderRadius: 20, fontSize: 11, fontWeight: 700, color: "white", cursor: "pointer", transition: "all 0.2s", boxShadow: "0 4px 12px rgba(33,131,128,0.2)" }}
              >
                Save Changes
              </button>
            </div>
          )}
        </div>

        {/* Lower row: Interactive Selectors */}
        <div style={{ display: "grid", gridTemplateColumns: "repeat(3, 1fr)", gap: 16, height: 260 }}>

          {/* Selector 1: Pastels */}
          <div style={{ background: "var(--glass-light)", borderRadius: 24, overflow: "hidden", position: "relative", border: "1px solid rgba(0,0,0,0.06)", display: "flex", flexDirection: "column", padding: 16 }}>
            <div style={{ fontSize: 11, fontWeight: 700, color: "var(--text-sub)", marginBottom: 12 }}>PIGMENTS</div>
            <div style={{ display: "flex", flexWrap: "wrap", gap: 8, overflowY: "auto", alignContent: "flex-start", flex: 1, paddingBottom: 16 }}>
              {PASTEL_COLORS.map(c => (
                <div key={c}
                  onClick={() => handleUpdateStaged({ color: c })}
                  style={{ width: 32, height: 32, borderRadius: "50%", background: c, cursor: "pointer", border: (stagedVisuals?.color || agent.color) === c ? '2px solid var(--text-main)' : '2px solid transparent', transition: "all 0.2s ease" }}
                />
              ))}
            </div>
          </div>

          {/* Selector 2: Assets Grid */}
          <div style={{ background: "var(--glass-light)", borderRadius: 24, overflow: "hidden", position: "relative", border: "1px solid rgba(0,0,0,0.06)", display: "flex", flexDirection: "column", padding: 16 }}>
            <div style={{ fontSize: 11, fontWeight: 700, color: "var(--text-sub)", marginBottom: 12, display: "flex", justifyContent: "space-between", alignItems: "center" }}>
              <span>ASSETS</span>
              <input
                type="text"
                placeholder="Search..."
                value={accessorySearch}
                onChange={e => setAccessorySearch(e.target.value)}
                style={{ background: "rgba(0,0,0,0.05)", border: "none", borderRadius: 12, padding: "4px 8px", fontSize: 9, width: 60, outline: "none", color: "var(--text-main)" }}
              />
            </div>
            <div style={{ display: "grid", gridTemplateColumns: "repeat(3, 1fr)", gap: 8, overflowY: "auto", flex: 1, paddingRight: 4, paddingBottom: 16 }}>
              {sortedAccessories.map(acc => {
                let isActive = stagedVisuals?.accessories?.includes(acc);
                return (
                  <img key={acc} src={acc}
                    onClick={() => {
                      const current = stagedVisuals?.accessories || [];
                      handleUpdateStaged({ accessories: isActive ? current.filter(x => x !== acc) : [...current, acc] });
                    }}
                    style={{ width: "100%", aspectRatio: "1/1", objectFit: "contain", background: "rgba(0,0,0,0.03)", borderRadius: 8, cursor: "pointer", border: isActive ? '2px solid var(--text-main)' : '2px solid transparent', transition: "all 0.1s ease" }}
                  />
                )
              })}
            </div>
          </div>

          {/* Selector 3: Habitats */}
          <div style={{ background: "var(--glass-light)", borderRadius: 24, overflow: "hidden", position: "relative", border: "1px solid rgba(0,0,0,0.06)", display: "flex", flexDirection: "column", padding: 16 }}>
            <div style={{ fontSize: 11, fontWeight: 700, color: "var(--text-sub)", marginBottom: 12 }}>HABITAT</div>
            <div style={{ display: "grid", gridTemplateColumns: "repeat(2, 1fr)", gap: 12, overflowY: "auto", flex: 1, alignContent: "flex-start", paddingRight: 4, paddingBottom: 16 }}>
              {HABITATS.map(h => (
                <div key={h}
                  onClick={() => handleUpdateStaged({ habitatId: h })}
                  style={{ background: "rgba(0,0,0,0.03)", borderRadius: 12, height: 100, overflow: "hidden", position: "relative", cursor: "pointer", border: stagedVisuals?.habitatId === h ? "2px solid #218380" : "2px solid rgba(0,0,0,0)", transition: "all 0.1s ease" }}>
                  <Canvas orthographic camera={{ position: [5, 5, 5], zoom: 16 }} style={{ pointerEvents: "none" }}>
                    <ambientLight intensity={1} />
                    <directionalLight position={[10, 20, 5]} intensity={1} />
                    <group position={[0, -0.6, 0]} rotation={[0, Math.PI / 4, 0]}>
                      <React.Suspense fallback={null}>
                        <TerrariumBase habitatId={h} />
                      </React.Suspense>
                    </group>
                  </Canvas>
                </div>
              ))}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

PersonalityTab.text:
function PersonalityTab({ agent }: { agent: AgentData }) {
  const initialFullPrompt = agent.personalityPrompt || "";
  const booksMatch = initialFullPrompt.match(/\n\nRecently Read Books: You have recently read the following books and found them very interesting: (.*?)(?=\n\n|$)/);
  const booksStr = booksMatch ? booksMatch[1] : "";
  const initialBooks = booksStr ? booksStr.replace(/\.$/, "").split(", ").filter(Boolean) : [];
  const base = initialFullPrompt.replace(/\n\nRecently Read Books: You have recently read the following books and found them very interesting: .*?(?=\n\n|$)/, "");

  const [prompt, setPrompt] = useState(base);
  const [recentlyRead, setRecentlyRead] = useState<string[]>(initialBooks);
  const [bookSearchQuery, setBookSearchQuery] = useState("");
  const [bookSearchResults, setBookSearchResults] = useState<any[]>([]);
  const [isSearchingBooks, setIsSearchingBooks] = useState(false);
  const [showBookDropdown, setShowBookDropdown] = useState(false);
  const searchTimeoutRef = useRef<any>(null);

  const [selectedModel, setSelectedModel] = useState<string>((agent.personality as any)?.active_model || "");

  const handleBookSearch = (query: string) => {
    setBookSearchQuery(query);
    setShowBookDropdown(true);
    if (!query.trim()) {
      setBookSearchResults([]);
      return;
    }
    if (searchTimeoutRef.current) clearTimeout(searchTimeoutRef.current);
    searchTimeoutRef.current = setTimeout(async () => {
      setIsSearchingBooks(true);
      try {
        const res = await fetch(`https://openlibrary.org/search.json?q=${encodeURIComponent(query)}&limit=5`);
        const data = await res.json();
        if (data && data.docs) {
          setBookSearchResults(data.docs);
        }
      } catch (e) { console.error(e); }
      setIsSearchingBooks(false);
    }, 400);
  };

  const [selectedFile, setSelectedFile] = useState("Library");
  const [fileContent, setFileContent] = useState("");
  const [isSaving, setIsSaving] = useState(false);
  const [fileSaveStatus, setFileSaveStatus] = useState("");

  useEffect(() => {
    if (selectedFile === "Library") return;
    setFileSaveStatus("");
    invoke<string>("read_workspace_file", { agentId: agent.id, filename: selectedFile })
      .then(content => setFileContent(content))
      .catch(err => {
        console.warn("Failed to read file", err);
        setFileContent("");
      });
  }, [agent.id, selectedFile]);

  const handleSaveFile = async () => {
    setIsSaving(true);
    setFileSaveStatus("Saving...");
    try {
      await invoke("write_workspace_file", { agentId: agent.id, filename: selectedFile, content: fileContent });
      setFileSaveStatus("Saved successfully!");
      setTimeout(() => setFileSaveStatus(""), 3000);
    } catch (e) {
      setFileSaveStatus("Error saving file: " + e);
    }
    setIsSaving(false);
  };

  const savePersonalityChanges = async (newRecentlyRead: string[]) => {
    try {
      if (typeof invoke === 'function') {
        let finalPrompt = prompt;
        if (newRecentlyRead.length > 0) {
          finalPrompt += `\n\nRecently Read Books: You have recently read the following books and found them very interesting: ${newRecentlyRead.join(', ')}.`;
        }
        await invoke("update_agent_personality", {
          agentId: agent.id,
          personality: { ...agent.personality, custom_instructions: finalPrompt }
        });

        useWorldStore.getState().setAgents(useWorldStore.getState().agents.map(a =>
          a.id === agent.id ? { 
            ...a, 
            personality: { ...a.personality, custom_instructions: finalPrompt },
            personalityPrompt: finalPrompt 
          } as AgentData : a
        ));
      }
    } catch (e) {
      console.error(e);
    }
  };

  // ── Model list for the Brain tab — sourced from Rust, not localhost:3001 ─────
  const [brainModels, setBrainModels] = useState<any[]>([]);
  useEffect(() => {
    invoke<any[]>("get_available_models")
      .then(models => setBrainModels(models))
      .catch(() => { /* gateway not yet up, will retry on next render */ });
  }, []);

  const HEAVY_ROLES_BRAIN = ["Strategist", "Analyst", "Researcher", "Engineer"];
  const getDynamicRecommendedModel = () => {
    const isHeavy = HEAVY_ROLES_BRAIN.includes(agent.role);
    // Prefer the provider for which a key is already set in this agent's Brain config
    const availableProviders = Object.entries(keys)
      .filter(([_, v]) => v && v.trim().length > 0)
      .map(([k]) => k === "Gemini" ? "Google Gemini" : k);

    let match = null;
    if (availableProviders.length > 0) {
      const prov = availableProviders[0];
      const strategy = isHeavy ? "heavy" : "light";
      match = brainModels.find((m: any) => m.provider === prov && m.strategy === strategy)
           || brainModels.find((m: any) => m.provider === prov);
    }
    if (!match) {
      match = brainModels.find((m: any) => m.strategy === (isHeavy ? "heavy" : "light"))
           || brainModels[0];
    }
    return { provider: match?.provider || "Google Gemini", model: `${match?.name || "Gemini 3.1 Flash Lite"} — ${match?.description || "Fastest Gemini 3 model (Preview)"}`, id: match?.id || "google/gemini-3.1-flash-lite-preview" };
  };

  const [keys, setKeys] = useState<{ [provider: string]: string }>({
    "OpenAI": "", "Anthropic": "", "Gemini": "", "Grok": ""
  });
  const [saveStatus, setSaveStatus] = useState<"idle" | "loading" | "success" | "error">("idle");

  const defaultModelInfo = getDynamicRecommendedModel();

  useEffect(() => {
    if (typeof invoke === 'function') {
      const providers = ["OpenAI", "Anthropic", "Gemini", "Grok"];
      providers.forEach(prov => {
        invoke("get_secret_cmd", { key: `agent_${agent.id}_${prov.toLowerCase()}_key` })
          .then(k => setKeys(prev => ({ ...prev, [prov]: k as string })))
          .catch(() => { });
      });
    }
  }, [agent.id]);

  const saveOverrides = async () => {
    setSaveStatus("loading");
    try {
      if (typeof invoke === 'function') {
        const providers = ["OpenAI", "Anthropic", "Gemini", "Grok"];
        for (const prov of providers) {
          const val = keys[prov];
          try {
            if (val && val.trim()) {
              await invoke("store_secret_cmd", { key: `agent_${agent.id}_${prov.toLowerCase()}_key`, value: val.trim() });
            } else {
              await invoke("delete_secret_cmd", { key: `agent_${agent.id}_${prov.toLowerCase()}_key` });
            }
          } catch (err) {
            // macOS keychain might throw if the key doesn't exist to delete. Ignore gracefully.
          }
        }

        // Model IDs from get_available_models() are already in "provider/model-name" format
        // (e.g. "google/gemini-3.1-flash-lite-preview"). No prefix construction needed.
        // Fallback to the Rust-side default if nothing is selected.
        const finalModel = selectedModel || defaultModelInfo?.id || "google/gemini-3.1-flash-lite-preview";

        // Synchronize updated keys directly to OpenClaw's auth-profiles.json layer
        let mappedKeys: Record<string, string> = {};
        if (keys["OpenAI"]) mappedKeys["OPENAI_API_KEY"] = keys["OpenAI"];
        if (keys["Anthropic"]) mappedKeys["ANTHROPIC_API_KEY"] = keys["Anthropic"];
        if (keys["Gemini"]) mappedKeys["GEMINI_API_KEY"] = keys["Gemini"];
        if (keys["Grok"]) mappedKeys["XAI_API_KEY"] = keys["Grok"];

        await invoke("sync_credentials", { agentId: agent.id, keys: mappedKeys });

        // Push personality state to SQLite. Use the full provider/model-name string.
        await invoke("update_agent_personality", {
          agentId: agent.id,
          personality: { ...agent.personality, active_model: finalModel }
        });
        // Update agent model in OpenClaw — model ID is already correctly formatted.
        await invoke("update_agent_model", { agentId: agent.id, model: finalModel });
      }
      setSaveStatus("success");
      setTimeout(() => setSaveStatus("idle"), 2000);
    } catch (e) {
      console.error(e);
      setSaveStatus("error");
    }
  };

  return (
    <div style={{ display: "flex", flexDirection: "column", height: "100%", paddingRight: 16, overflowY: "auto" }}>


      <h1 style={{ fontSize: 28, fontWeight: 700, color: "var(--text-main)", margin: "0 0 8px 0", flexShrink: 0 }}>Brain</h1>
      <p style={{ fontSize: 14, color: "var(--text-sub)", marginBottom: 28, flexShrink: 0 }}>Shape how {agent.name} thinks, acts, and appears.</p>



      <div style={{ display: "flex", flexDirection: "column", gap: 20, flex: 1 }}>
        <div style={{ display: "flex", gap: 12 }}>
          {["Library", "Memory", "USER.md", "IDENTITY.md", "TOOLS.md", "SOUL.md"].map(f => (
            <button
              key={f}
              onClick={() => setSelectedFile(f)}
              style={{
                padding: "8px 16px", borderRadius: 8, border: "none",
                background: selectedFile === f ? "#218380" : "rgba(0,0,0,0.05)",
                color: selectedFile === f ? "#FFF" : "var(--text-main)",
                fontWeight: 600, cursor: "pointer", fontSize: 13
              }}
            >
              {f}
            </button>
          ))}
        </div>

        {selectedFile === "Library" ? (
          <div style={{ ...glass(0.5), padding: 24, borderRadius: 16, display: "flex", flexDirection: "column", flex: 1 }}>
            <div style={{ fontSize: 12, fontWeight: 600, color: "var(--text-main)", marginBottom: 6 }}>Training Books</div>
            <div style={{ fontSize: 11, color: "var(--text-sub)", marginBottom: 12 }}>These books are injected into the agent's context to subtly shift their default decision making.</div>

            <div style={{ flex: 1, overflowY: "auto", display: "flex", flexDirection: "column" }}>
              <div style={{ display: "flex", flexWrap: "wrap", gap: 8, marginBottom: 16 }}>
                {recentlyRead.length === 0 && <span style={{ fontSize: 12, color: "var(--text-sub)", fontStyle: "italic" }}>No books assigned.</span>}
                {recentlyRead.map(book => (
                  <div key={book} style={{ padding: "6px 12px", background: "#3c6663", color: "var(--surface-card)", borderRadius: 16, fontSize: 12, display: "flex", alignItems: "center", gap: 6 }}>
                    {book}
                    <span style={{ cursor: "pointer", opacity: 0.8 }} onClick={() => {
                        const nextRead = recentlyRead.filter(b => b !== book);
                        setRecentlyRead(nextRead);
                        savePersonalityChanges(nextRead);
                    }}>×</span>
                  </div>
                ))}
              </div>

              <div style={{ display: "flex", gap: 8, marginTop: "auto", position: "relative" }}>
                <div style={{ flex: 1, position: "relative" }}>
                  <input
                    value={bookSearchQuery}
                    onChange={e => handleBookSearch(e.target.value)}
                    onFocus={() => setShowBookDropdown(true)}
                    onBlur={() => setTimeout(() => setShowBookDropdown(false), 200)}
                    placeholder="Search for a book by title, author, or subject..."
                    style={{ width: "100%", padding: "8px 12px", borderRadius: 8, border: "1px solid rgba(0,0,0,0.1)", fontSize: 12, outline: "none", fontFamily: "inherit", boxSizing: "border-box" }}
                    onKeyDown={e => {
                      if (e.key === "Enter" && bookSearchQuery.trim()) {
                        const nextRead = [...recentlyRead, bookSearchQuery.trim()];
                        setRecentlyRead(nextRead);
                        setBookSearchQuery("");
                        setShowBookDropdown(false);
                        savePersonalityChanges(nextRead);
                      }
                    }}
                  />
                  {showBookDropdown && (bookSearchResults.length > 0 || isSearchingBooks) && (
                    <div style={{
                      position: "absolute", bottom: "100%", left: 0, right: 0, marginBottom: 8,
                      background: "var(--surface-card)", border: "1px solid rgba(0,0,0,0.1)",
                      borderRadius: 8, boxShadow: "0 -4px 12px rgba(0,0,0,0.1)", zIndex: 10,
                      maxHeight: 220, overflowY: "auto"
                    }}>
                      {isSearchingBooks ? (
                        <div style={{ padding: 12, fontSize: 12, color: "var(--text-sub)", textAlign: "center" }}>Searching...</div>
                      ) : (
                        bookSearchResults.map((doc: any, i: number) => (
                          <div key={i} style={{
                            padding: "8px 12px", display: "flex", alignItems: "center", gap: 12,
                            cursor: "pointer", borderBottom: i < bookSearchResults.length - 1 ? "1px solid rgba(0,0,0,0.05)" : "none",
                          }} onClick={() => {
                            const titleStr = `${doc.title}${doc.author_name ? ` by ${doc.author_name[0]}` : ''}`;
                            const nextRead = [...recentlyRead, titleStr];
                            setRecentlyRead(nextRead);
                            setBookSearchQuery("");
                            setShowBookDropdown(false);
                            savePersonalityChanges(nextRead);
                          }}
                          onMouseEnter={e => e.currentTarget.style.background = "var(--surface-base)"}
                          onMouseLeave={e => e.currentTarget.style.background = "transparent"}>
                            {doc.cover_i ? (
                              <img src={`https://covers.openlibrary.org/b/id/${doc.cover_i}-S.jpg`} style={{ width: 24, height: 36, objectFit: "cover", borderRadius: 2 }} />
                            ) : (
                              <div style={{ width: 24, height: 36, background: "var(--border-subtle)", borderRadius: 2, display: "flex", alignItems: "center", justifyContent: "center" }}><span style={{ fontSize: 10, color: "var(--text-muted)" }}>?</span></div>
                            )}
                            <div style={{ display: "flex", flexDirection: "column" }}>
                              <div style={{ fontSize: 13, fontWeight: 600, color: "var(--text-main)" }}>{doc.title}</div>
                              {doc.author_name && <div style={{ fontSize: 11, color: "var(--text-sub)" }}>{doc.author_name.join(", ")}</div>}
                            </div>
                          </div>
                        ))
                      )}
                    </div>
                  )}
                </div>
                <button onClick={() => {
                  if (bookSearchQuery.trim()) {
                    const nextRead = [...recentlyRead, bookSearchQuery.trim()];
                    setRecentlyRead(nextRead);
                    setBookSearchQuery("");
                    setShowBookDropdown(false);
                    savePersonalityChanges(nextRead);
                  }
                }} style={{ padding: "8px 16px", borderRadius: 8, border: "none", background: "var(--surface-base)", color: "var(--text-main)", cursor: "pointer", fontSize: 12, fontWeight: 600, fontFamily: "inherit" }}>Add</button>
              </div>
            </div>
          </div>
        ) : selectedFile === "Memory" ? (
          <div style={{ flex: 1, overflowY: "auto" }}>
            <MemoryTab agent={agent} isEmbedded={true} />
          </div>
        ) : (
          <div style={{ flex: 1, display: "flex", flexDirection: "column", position: "relative" }}>
            <textarea
              value={fileContent}
              onChange={e => setFileContent(e.target.value)}
              style={{
                flex: 1, width: "100%", padding: 20, borderRadius: 12,
                border: "1px solid rgba(0,0,0,0.1)", background: "var(--surface-bg)",
                color: "var(--text-main)", fontSize: 14, fontFamily: "'Fira Code', monospace",
                resize: "none", outline: "none", minHeight: 300
              }}
            />
            <div style={{ position: "absolute", bottom: 20, right: 20, display: "flex", alignItems: "center", gap: 12 }}>
              {fileSaveStatus && <span style={{ fontSize: 13, color: fileSaveStatus.includes("Error") ? "#E57373" : "#218380", fontWeight: 600 }}>{fileSaveStatus}</span>}
              <button
                onClick={handleSaveFile}
                disabled={isSaving}
                style={{
                  padding: "10px 24px", borderRadius: 8, border: "none",
                  background: "#3c6663", color: "#FFF", fontWeight: 700,
                  cursor: isSaving ? "not-allowed" : "pointer", fontSize: 14,
                  boxShadow: "0 4px 12px rgba(33,131,128,0.2)"
                }}
              >
                {isSaving ? "Saving..." : "Save File"}
              </button>
            </div>
          </div>
        )}
      </div>

    </div>
  );
}

PermissionsTab.text:
// ─── Permissions Tab ─────────────────────────────────────────────────────────

function PermissionsTab({ agent }: { agent: AgentData }) {
  const toggle = useWorldStore(s => s.togglePermission);
  const OPENCLAW_PERMISSIONS_GUIDE: Record<string, { desc: string, recommended: string }> = {
    ext_network: { desc: "Allow outbound API calls and web access.", recommended: "On for agents needing web search or external APIs. Off for completely local/private agents." },
    int_network: { desc: "Communicate with other agents via data handoffs.", recommended: "On if you have multiple agents collaborating." },
    autonomous: { desc: "Run tasks without manual approval.", recommended: "Off by default. Turn on only for trusted agents with well-defined tasks." },
    scheduled: { desc: "Execute on cron schedules.", recommended: "On for background agents like cron jobs or recurring reminders." },
    memory_write: { desc: "Store long-term data and learnings.", recommended: "On for most agents so they can remember context over time." },
    file_read: { desc: "Read files in scoped directories.", recommended: "On if the agent needs to read your workspace documents." },
    file_write: { desc: "Create and modify files.", recommended: "On for coder or writer agents. Off for read-only assistants." },
    payments: { desc: "Request virtual cards for purchases.", recommended: "Off unless the agent specifically handles procurement." },
    spend_auto: { desc: "Auto-approve purchases under threshold.", recommended: "Off unless you explicitly trust the agent with real money." },
    imessage: { desc: "Read and reply to text messages.", recommended: "On for communication agents. Off for internal tools." },
    photos: { desc: "Access local photo library database.", recommended: "Off unless the agent is specifically for photo management." }
  };

  return (
    <div>
      <h1 style={{ fontSize: 28, fontWeight: 700, color: "var(--text-main)", margin: "0 0 8px 0" }}>Permissions</h1>
      <p style={{ fontSize: 14, color: "var(--text-sub)", marginBottom: 28 }}>
        Granular control over {agent.name}'s capabilities. Changes take effect immediately.
      </p>

      {/* Isolation badge */}
      <div style={{
        ...glass(0.5), padding: "14px 20px", borderRadius: 12, marginBottom: 20,
        display: "flex", alignItems: "center", gap: 12,
        borderLeft: "3px solid #6B6BAE",
      }}>
        <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="#6B6BAE" strokeWidth={2} strokeLinecap="round" strokeLinejoin="round">
          <path d="M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z" />
        </svg>
        <div>
          <div style={{ fontSize: 13, fontWeight: 600, color: "var(--text-main)" }}>Shared Container</div>
          <div style={{ fontSize: 11, color: "var(--text-sub)" }}>This agent runs in the shared Gateway. Switch to isolated for OS-level sandboxing.</div>
        </div>
        <div style={{ flex: 1 }} />
        <button
          id="isolate-btn"
          onClick={async () => {
            const btn = document.getElementById('isolate-btn');
            const wasIsolated = agent.isolated;
            if (btn) btn.innerText = "Rebooting...";
            try {
              if (typeof invoke === 'function') {
                await invoke("toggle_agent_isolation", {
                  agentId: agent.id,
                  isolated: !wasIsolated
                });
                useWorldStore.getState().toggleIsolation(agent.id);
              }
            } catch (e) {
              console.error("Failed isolation toggle", e);
            } finally {
              if (btn) btn.innerText = !wasIsolated ? "Join Shared" : "Isolate";
            }
          }}
          style={{
            padding: "6px 14px", borderRadius: 8, border: "1px solid #6B6BAE",
            background: agent.isolated ? "#6B6BAE" : "transparent", color: agent.isolated ? "var(--surface-card)" : "#6B6BAE", fontSize: 12, fontWeight: 600,
            cursor: "pointer", fontFamily: "inherit", transition: "all 0.2s"
          }}>{agent.isolated ? "Un-Isolate" : "Isolate"}</button>
      </div>

      <div style={{ marginBottom: 32 }}>
        <div style={{
          padding: "12px 16px", background: "rgba(0,0,0,0.02)", borderTopLeftRadius: 14, borderTopRightRadius: 14,
          borderBottom: `2px solid var(--text-main)`, display: "flex", flexDirection: "column"
        }}>
          <div style={{ fontSize: 14, fontWeight: 800, color: "var(--text-main)", marginBottom: 4 }}>OpenClaw Permissions</div>
          <div style={{ fontSize: 12, color: "var(--text-sub)" }}>Configure the core capabilities of the OpenClaw agent.</div>
        </div>
        <div style={{ ...glass(0.5), borderBottomLeftRadius: 14, borderBottomRightRadius: 14, overflow: "hidden" }}>
          {agent.permissions.map((p, i, arr) => {
            const guide = OPENCLAW_PERMISSIONS_GUIDE[p.id] || { desc: p.description, recommended: "Use your best judgement." };
            return (
              <div key={p.id} style={{
                display: "flex", justifyContent: "space-between", alignItems: "center",
                padding: "14px 20px",
                borderBottom: i < arr.length - 1 ? "1px solid rgba(0,0,0,0.04)" : "none",
              }}>
                <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
                  <div>
                    <div style={{ fontSize: 13, fontWeight: 700, color: "var(--text-main)" }}>{p.label}</div>
                    <div style={{ fontSize: 11, color: "var(--text-sub)", marginTop: 4 }}>{guide.desc}</div>
                  </div>
                  <div title={guide.recommended} style={{
                    width: 16, height: 16, borderRadius: "50%", background: "var(--surface-card)", border: "1px solid rgba(0,0,0,0.1)",
                    display: "flex", alignItems: "center", justifyContent: "center", fontSize: 10, fontWeight: "bold", color: "var(--text-sub)", cursor: "help"
                  }}>?</div>
                </div>
                <Toggle enabled={p.enabled} onChange={async () => {
                  toggle(agent.id, p.id);
                  try {
                    if (typeof (window as any).__TAURI_INTERNALS__?.invoke === 'function') {
                      const invoke = (window as any).__TAURI_INTERNALS__.invoke;
                      const newPerms = agent.permissions.map(x => x.id === p.id ? { ...x, enabled: !x.enabled } : x);
                      const capabilitiesObj: any = {};
                      newPerms.forEach(px => capabilitiesObj[px.id] = px.enabled);
                      await invoke("update_agent_capabilities", {
                        agentId: agent.id,
                        capabilities: capabilitiesObj
                      });
                    }
                  } catch (e) { console.error("Failed to update capabilities", e); }
                }} />
              </div>
            );
          })}
        </div>
      </div>
    </div>
  );
}

MemoryTab.text:
// ─── Memory Tab ──────────────────────────────────────────────────────────────

function MemoryTab({ agent, isEmbedded }: { agent: AgentData; isEmbedded?: boolean }) {
  const memories = agent.memories || [];
  const { setAgents } = useWorldStore();
  const [newMemoryText, setNewMemoryText] = useState("");
  const [newMemoryType, setNewMemoryType] = useState("learned");
  const [saveStatus, setSaveStatus] = useState<"idle" | "loading" | "success" | "error">("idle");

  const typeColors: Record<string, string> = { learned: "#4A9E96", experience: "#5B88A6", preference: "#8B6AAE", context: "#D4A04A" };

  const handleCreateMemory = async () => {
    if (!newMemoryText.trim()) return;
    setSaveStatus("loading");
    try {
      const newMem = {
        id: Math.random().toString(36).substring(7),
        type: newMemoryType,
        text: newMemoryText.trim(),
        when: new Date().toISOString(),
        confidence: 1.0
      };

      const updatedMemories = [newMem, ...memories];
      const { invoke } = await import('@tauri-apps/api/core');
      await invoke("update_agent_memories", { agentId: agent.id, memories: updatedMemories });

      setAgents(useWorldStore.getState().agents.map(a =>
        a.id === agent.id ? { ...a, memories: updatedMemories } as AgentData : a
      ));

      setNewMemoryText("");
      setSaveStatus("success");
      setTimeout(() => setSaveStatus("idle"), 2000);
    } catch (err) {
      console.error(err);
      setSaveStatus("error");
    }
  };

  const handleDeleteMemory = async (memId: string) => {
    try {
      const updatedMemories = memories.filter((m: any) => m.id !== memId);
      const { invoke } = await import('@tauri-apps/api/core');
      await invoke("update_agent_memories", { agentId: agent.id, memories: updatedMemories });

      setAgents(useWorldStore.getState().agents.map(a =>
        a.id === agent.id ? { ...a, memories: updatedMemories } as AgentData : a
      ));
    } catch (err) {
      console.error(err);
    }
  };

  return (
    <div style={{ height: isEmbedded ? "100%" : "auto" }}>
      {!isEmbedded && (
        <>
          <h1 style={{ fontSize: 28, fontWeight: 700, color: "var(--text-main)", margin: "0 0 8px 0" }}>Memory</h1>
          <p style={{ fontSize: 14, color: "var(--text-sub)", marginBottom: 28 }}>
            What {agent.name} has learned and remembers. Memories are versioned and can be pruned.
          </p>
        </>
      )}

      <div style={{ display: "flex", gap: 8, marginBottom: 20 }}>
        {["All", "Learned", "Experience", "Preference"].map(f => (
          <button key={f} style={{
            padding: "6px 14px", borderRadius: 20, border: "1px solid rgba(0,0,0,0.08)",
            background: f === "All" ? "#3c6663" : "var(--glass-light)",
            color: f === "All" ? "var(--surface-card)" : "var(--text-sub)",
            fontSize: 12, fontWeight: 500, cursor: "pointer", fontFamily: "inherit",
          }}>{f}</button>
        ))}
      </div>

      <div style={{ ...glass(0.5), padding: 20, borderRadius: 16, marginBottom: 24 }}>
        <div style={{ fontSize: 13, fontWeight: 600, color: "var(--text-main)", marginBottom: 12 }}>Inject Manual Core Memory</div>
        <div style={{ display: "flex", gap: 12 }}>
          <select value={newMemoryType} onChange={e => setNewMemoryType(e.target.value)} style={{ padding: "10px 12px", borderRadius: 8, border: "1px solid rgba(0,0,0,0.1)", background: "var(--surface-card)", outline: "none" }}>
            <option value="learned">Learned Fact</option>
            <option value="experience">Experience</option>
            <option value="preference">Preference</option>
            <option value="context">Context</option>
          </select>
          <input
            value={newMemoryText}
            onChange={e => setNewMemoryText(e.target.value)}
            onKeyDown={e => e.key === "Enter" && handleCreateMemory()}
            placeholder="e.g. Only use the main branch for deployment."
            style={{ flex: 1, padding: "10px 14px", borderRadius: 8, border: "1px solid rgba(0,0,0,0.1)", background: "var(--surface-card)", outline: "none", fontSize: 13 }}
          />
          <button onClick={handleCreateMemory} disabled={saveStatus === "loading" || !newMemoryText.trim()} style={{
            padding: "10px 20px", borderRadius: 8, border: "none", background: !newMemoryText.trim() ? "var(--border-subtle)" : "#3c6663",
            color: !newMemoryText.trim() ? "#A0A0A0" : "var(--surface-card)", fontWeight: 600, cursor: !newMemoryText.trim() ? "not-allowed" : "pointer"
          }}>
            {saveStatus === "loading" ? "Saving..." : saveStatus === "success" ? "Saved!" : "Inject"}
          </button>
        </div>
      </div>

      <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
        {memories.length === 0 ? (
          <div style={{ padding: "40px 20px", textAlign: "center", color: "var(--text-sub)", fontSize: 14 }}>
            {agent.name} doesn't have any memories yet.<br />Memories are formed asynchronously as the agent works.
          </div>
        ) : (
          memories.map((m: any, i: number) => (
            <div key={m.id || i} style={{ ...glass(0.5), padding: "16px 20px", borderRadius: 14, borderLeft: `3px solid ${typeColors[m.type] || typeColors["learned"]}` }}>
              <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start" }}>
                <div style={{ flex: 1 }}>
                  <div style={{ display: "flex", gap: 8, alignItems: "center", marginBottom: 6 }}>
                    <span style={{
                      fontSize: 10, fontWeight: 600, textTransform: "uppercase", letterSpacing: "0.05em",
                      color: typeColors[m.type], background: `${typeColors[m.type]}15`, padding: "2px 8px", borderRadius: 4,
                    }}>{m.type}</span>
                    <span style={{ fontSize: 11, color: "var(--text-muted)" }}>{m.when}</span>
                  </div>
                  <div style={{ fontSize: 13, color: "var(--text-main)", lineHeight: 1.5 }}>{m.text}</div>
                </div>
                <div style={{ textAlign: "right", marginLeft: 16 }}>
                  <div style={{ fontSize: 10, color: "var(--text-sub)" }}>Confidence</div>
                  <div style={{ fontSize: 14, fontWeight: 600, color: "var(--text-main)", marginBottom: 8 }}>{Math.round((m.confidence || 1.0) * 100)}%</div>
                  <button onClick={() => handleDeleteMemory(m.id)} style={{ background: "none", border: "none", cursor: "pointer", opacity: 0.5 }}>🗑️</button>
                </div>
              </div>
            </div>
          ))
        )}
      </div>
    </div>
  );
}

SpendTab.text:
// ─── Spend Tab ───────────────────────────────────────────────────────────────

function SpendTab({ agent }: { agent: AgentData }) {
  const [budget, setBudget] = useState<any>(null);
  const [history, setHistory] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);

  // Filters
  const [searchQuery, setSearchQuery] = useState("");
  const [statusFilter, setStatusFilter] = useState("All");

  useEffect(() => {
    const fetchData = async () => {
      setLoading(true);
      try {
        const { invoke } = await import('@tauri-apps/api/core');
        const budgetRes = await invoke('get_agent_budget', { agentId: agent.id });
        setBudget(budgetRes);
        const historyRes: any = await invoke('get_purchase_history', { agentId: agent.id });
        setHistory(Array.isArray(historyRes) ? historyRes : []);
      } catch (e) {
        console.error("Failed to load spend data", e);
      }
      setLoading(false);
    };
    fetchData();
  }, [agent.id]);

  if (loading) return <div style={{ color: "var(--text-sub)", fontSize: 14 }}>Loading financial data...</div>;
  if (!budget) return <div style={{ color: "var(--text-sub)", fontSize: 14 }}>Failed to map budget pipeline...</div>;

  const filteredHistory = history.filter(record => {
    const matchesSearch = record.merchant?.toLowerCase().includes(searchQuery.toLowerCase()) || 
                          record.category?.toLowerCase().includes(searchQuery.toLowerCase());

    let isApproved = record.decision === "Approved" || record.decision === "approved" || record.decision?.Approved === null;
    let isDenied = record.decision === "Denied" || record.decision === "denied" || record.decision?.Denied;

    let matchesStatus = true;
    if (statusFilter === "Approved") matchesStatus = isApproved;
    if (statusFilter === "Denied") matchesStatus = isDenied;

    return matchesSearch && matchesStatus;
  });

  return (
    <div style={{ paddingBottom: 64 }}>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-end", marginBottom: 24 }}>
        <div>
          <h1 style={{ fontSize: 28, fontWeight: 700, color: "var(--text-main)", margin: "0 0 8px 0" }}>Purchase Execution Log</h1>
          <p style={{ fontSize: 14, color: "var(--text-sub)", margin: 0 }}>
            History of {agent.name}'s simulated and executed real-world transactions.
          </p>
        </div>
        <div style={{ fontSize: 13, fontWeight: 600, color: "var(--text-main)", background: "var(--glass-light)", padding: "8px 16px", borderRadius: 12, border: "1px solid rgba(0,0,0,0.05)" }}>
          Daily Spend: ${(budget.daily_spent_cents / 100).toFixed(2)} / Monthly: ${(budget.monthly_spent_cents / 100).toFixed(2)}
        </div>
      </div>

      {/* Filters */}
      <div style={{ display: "flex", gap: 12, marginBottom: 20 }}>
        <input 
          type="text" 
          placeholder="Search merchant or category..." 
          value={searchQuery}
          onChange={e => setSearchQuery(e.target.value)}
          style={{ flex: 1, padding: "8px 12px", borderRadius: 8, border: "1px solid var(--border-subtle)", background: "var(--surface-card)", fontSize: 13, outline: "none" }}
        />
        <select 
          value={statusFilter} 
          onChange={e => setStatusFilter(e.target.value)}
          style={{ padding: "8px 12px", borderRadius: 8, border: "1px solid var(--border-subtle)", background: "var(--surface-card)", fontSize: 13, outline: "none", cursor: "pointer" }}
        >
          <option value="All">All Statuses</option>
          <option value="Approved">Approved</option>
          <option value="Denied">Denied</option>
        </select>
      </div>

      {filteredHistory.length === 0 ? (
        <div style={{ textAlign: "center", padding: "40px 20px", color: "var(--text-sub)", fontSize: 14, ...glass(0.4), borderRadius: 16 }}>
          {history.length === 0 ? "There are no recent agent transactions on record." : "No transactions match your filters."}
        </div>
      ) : (
        <div style={{ ...glass(0.6), borderRadius: 16, overflow: "hidden" }}>
          <table style={{ width: "100%", borderCollapse: "collapse" }}>
            <thead>
              <tr style={{ background: "var(--border-subtle)", textAlign: "left" }}>
                <th style={{ padding: "12px 20px", fontSize: 12, fontWeight: 600, color: "var(--text-sub)" }}>Date/Time</th>
                <th style={{ padding: "12px 20px", fontSize: 12, fontWeight: 600, color: "var(--text-sub)" }}>Merchant</th>
                <th style={{ padding: "12px 20px", fontSize: 12, fontWeight: 600, color: "var(--text-sub)" }}>Category</th>
                <th style={{ padding: "12px 20px", fontSize: 12, fontWeight: 600, color: "var(--text-sub)" }}>Status</th>
                <th style={{ padding: "12px 20px", fontSize: 12, fontWeight: 600, color: "var(--text-sub)", textAlign: "right" }}>Amount</th>
              </tr>
            </thead>
            <tbody>
              {filteredHistory.map((record, i) => (
                <tr key={record.id || i} style={{ borderTop: "1px solid rgba(0,0,0,0.04)" }}>
                  <td style={{ padding: "14px 20px", fontSize: 13, color: "var(--text-main)" }}>{new Date(record.timestamp || Date.now()).toLocaleString()}</td>
                  <td style={{ padding: "14px 20px", fontSize: 13, fontWeight: 600, color: "var(--text-main)" }}>{record.merchant}</td>
                  <td style={{ padding: "14px 20px", fontSize: 13, color: "var(--text-sub)" }}>{record.category}</td>
                  <td style={{ padding: "14px 20px", fontSize: 13 }}>
                    {record.decision === "Approved" || record.decision === "approved" || record.decision?.Approved === null
                      ? <span style={{ color: "#4A9E96", background: "#4A9E9615", padding: "4px 8px", borderRadius: 4, fontWeight: 600, fontSize: 11 }}>APPROVED</span>
                      : record.decision === "Denied" || record.decision === "denied" || record.decision?.Denied
                        ? <span style={{ color: "#E57373", background: "#E5737315", padding: "4px 8px", borderRadius: 4, fontWeight: 600, fontSize: 11 }}>DENIED</span>
                        : <span style={{ color: "#D4A04A", background: "#D4A04A15", padding: "4px 8px", borderRadius: 4, fontWeight: 600, fontSize: 11 }}>REQUIRES APPROVAL</span>
                    }
                  </td>
                  <td style={{ padding: "14px 20px", fontSize: 14, fontWeight: 700, color: "var(--text-main)", textAlign: "right" }}>
                    ${((record.amount_cents || 0) / 100).toFixed(2)}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
    </div>
  );
}

